def reach_changes(A, changes, neigh):
 seeds={(r,c) for r in range(len(A)) for c in range(len(A[0])) if A[r][c] in (2,3,4)}
 allowed=changes|seeds;q=deque(seeds);seen=set(seeds)
 while q:
  r,c=q.popleft()
  for dr,dc in neigh:
   t=r+dr,c+dc
   if t in allowed and t not in seen:seen.add(t);q.append(t)
 return len(changes-seen),len(seen),len(changes)
